#define DATA_TYPE double

static void kernel_ludcmp(int n, DATA_TYPE POLYBENCH_2D(A, N+1, N+1, n+1, n+1), DATA_TYPE POLYBENCH_1D(b, N+1, n+1), DATA_TYPE POLYBENCH_1D(x, N+1, n+1), DATA_TYPE POLYBENCH_1D(y, N+1, n+1)) {
    int i, j, k;
    DATA_TYPE w;

    // Initialize b[0]
    b[0] = 1.0;

    // Parallelize the outer loop over rows
#pragma omp parallel for schedule(static)
    for (i = 0; i <= n; ++i) {
        // Compute the first half of matrix A
        for (j = i + 1; j <= n; ++j) {
            w = A[j][i];
            for (k = 0; k < i; ++k) {
                w -= A[j][k] * A[k][i];
            }
            A[j][i] = w;
        }

        // Barrier to synchronize threads
#pragma omp barrier

        // Update the current row of matrix A
        for (j = i + 1; j <= n; ++j) {
            w = A[j][i];
            for (k = 0; k < i; ++k) {
                w -= A[j][k] * A[k][i];
            }
            A[j][i] = w;
        }

        // Solve for y
        y[i] = b[i];

        // Back substitution
        x[i] = y[i];
        for (j = i - 1; j >= 0; --j) {
            w = A[j][i];
            for (k = j + 1; k <= i; ++k) {
                w -= A[j][k] * x[k];
            }
            x[j] = w / A[j][j];
        }
    }
}

