for (k = 0; k < n - 1; ++k) {
    // Normalize the pivot row
    A[k][k] = 1 / A[k][k];
    // Update the upper triangular portion
    for (j = k + 1; j < n; ++j) {
        A[j][k] *= A[k][k];
    }
